def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out"""
    # Simple approach: find first difference and determine what needs to change
    min_len = min(len(s_in), len(s_out))

    # Find where they start to differ
    pos = 0
    while pos < min_len and s_in[pos] == s_out[pos]:
        pos += 1

    # If we've reached the end of one string, check if it's just length difference
    if pos >= min_len:
        if len(s_in) < len(s_out):
            # Insertion case
            return (s_in[pos-1], s_out[pos-1:], pos-1) if pos > 0 else ("", s_out[pos:], pos)
        else:
            # Deletion case  
            return (s_in[pos], "", pos)

    # Found a difference at position pos
    # Let's see what substring needs to be replaced
    # We'll try to find the longest common prefix/suffix to determine pattern

    # Try simple replacement
    if len(s_in) == len(s_out):
        # Same length - simple replacement
        return (s_in[pos], s_out[pos], pos)
    elif len(s_in) < len(s_out):
        # Insertion
        # Look for what was inserted
        return (s_in[pos], s_out[pos:pos+len(s_in)-pos+1], pos) if pos < len(s_in) else ("", s_out[pos:], pos)
    else:
        # Deletion
        return (s_in[pos:pos+len(s_out)-pos+1], "", pos)

